record.field:
from datetime import datetime, timedelta
import re

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
madrid_tz = pytz.timezone('Europe/Madrid')
now_utc = fields.Datetime.from_string(fields.Datetime.now())
now_utc = now_utc.replace(minute=0, second=0, microsecond=0)


def _json_loads(raw_value):
    try:
        return json.loads(raw_value or '{}') or {}
    except Exception:
        return {}


def _parse_depth(sensor_record):
    sensor_cfg = _json_loads(sensor_record.remotecontrol_params)
    depth_cm = sensor_cfg.get('depth_cm') or sensor_cfg.get('depth') or 0
    try:
        depth_cm = int(depth_cm)
    except Exception:
        depth_cm = 0
    if not depth_cm:
        match = re.search(r'(\d+)', sensor_record.name or '')
        if match:
            depth_cm = int(match.group(1))
    return depth_cm


def _local_midnight_to_utc(date_str):
    date_value = fields.Date.from_string(date_str)
    local_dt = datetime(
        date_value.year,
        date_value.month,
        date_value.day,
        0,
        0,
        0,
    )
    localized = madrid_tz.localize(local_dt, is_dst=False)
    return localized.astimezone(pytz.UTC).replace(tzinfo=None)


def _get_initial_dt(sensor_record):
    last_reading = Reading.search([
        ('sensor_id', '=', sensor_record.id),
        ('active', '=', True),
    ], order='measurement_time desc', limit=1)
    if last_reading and last_reading.measurement_time:
        return fields.Datetime.from_string(
            last_reading.measurement_time) + timedelta(hours=1)

    sensor_cfg = _json_loads(sensor_record.remotecontrol_params)
    device_cfg = _json_loads(sensor_record.device_id.remotecontrol_params)
    start_date = (
        sensor_cfg.get('start_date') or
        device_cfg.get('start_date') or
        ''
    )
    if not start_date:
        current_date = fields.Date.from_string(fields.Date.today())
        start_date = '%s-01-01' % current_date.year
    return _local_midnight_to_utc(start_date)


domain = [
    ('active', '=', True),
    ('device_id.active', '=', True),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    domain.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(domain, order='device_id, name')
plan = []
skipped = []

for sensor in sensors:
    depth_cm = _parse_depth(sensor)
    if depth_cm <= 0:
        skipped.append({
            'sensor_id': sensor.id,
            'sensor_name': sensor.name,
            'device_name': sensor.device_id.name,
            'reason': 'No depth found in remotecontrol_params or sensor name.',
        })
        continue

    initial_dt = _get_initial_dt(sensor)
    if initial_dt > now_utc:
        continue

    plan.append({
        'device_id': sensor.device_id.id,
        'device_name': sensor.device_id.name,
        'sensor_id': sensor.id,
        'sensor_name': sensor.name,
        'depth_cm': depth_cm,
        'start_dt': initial_dt.strftime('%Y-%m-%d %H:%M:%S'),
        'end_dt': now_utc.strftime('%Y-%m-%d %H:%M:%S'),
    })

bag['sensors_plan'] = plan
bag['skipped_sensors'] = skipped
bag['planned_sensors'] = len(plan)
bag['skipped_sensors_count'] = len(skipped)

Remote.message_post(
    body=u'[IKOS Techs] Plan generated: sensors=%s skipped=%s' % (
        len(plan), len(skipped))
)
